-- ABOUTME: Создаёт три предметные таблицы истории и атомарно загружает системный каталог с аудитом.
-- ABOUTME: Повтор сохраняет ручные названия и новые строки; закреплённые ID/code/category конфликты явно отвергаются.
CREATE SCHEMA IF NOT EXISTS history;
CREATE TABLE IF NOT EXISTS history.migrations(version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE IF NOT EXISTS history.sys_categories(
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id>0),
 code text NOT NULL UNIQUE CHECK(code ~ '^[a-z][a-z0-9_]*$' AND length(code) BETWEEN 1 AND 64),
 name text NOT NULL CHECK(length(name) BETWEEN 1 AND 128),
 description text NOT NULL CHECK(length(description)<=512)
);
CREATE TABLE IF NOT EXISTS history.sys_types(
 id integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY CHECK(id>0),
 category_id integer NOT NULL REFERENCES history.sys_categories(id),
 code text NOT NULL UNIQUE CHECK(code ~ '^[a-z][a-z0-9_]*$' AND length(code) BETWEEN 1 AND 64),
 name text NOT NULL CHECK(length(name) BETWEEN 1 AND 128),
 description text NOT NULL CHECK(length(description)<=512)
);
CREATE TABLE IF NOT EXISTS history.events(
 id uuid NOT NULL,
 source text NOT NULL CHECK(source ~ '^[a-z][a-z0-9_]*$' AND length(source) BETWEEN 1 AND 64),
 type_id integer NOT NULL REFERENCES history.sys_types(id),
 occurred_at timestamptz NOT NULL CHECK(isfinite(occurred_at)),
 recorded_at timestamptz NOT NULL DEFAULT clock_timestamp() CHECK(isfinite(recorded_at)),
 actor_id text CHECK(actor_id IS NULL OR length(actor_id) BETWEEN 1 AND 255),
 scope_type text NOT NULL CHECK(scope_type ~ '^[a-z][a-z0-9_]*$' AND length(scope_type) BETWEEN 1 AND 32),
 scope_id text NOT NULL CHECK(length(scope_id) BETWEEN 1 AND 255),
 object_type text CHECK(object_type IS NULL OR length(object_type) BETWEEN 1 AND 64),
 object_id text CHECK(object_id IS NULL OR length(object_id) BETWEEN 1 AND 255),
 data jsonb NOT NULL DEFAULT '{}'::jsonb CHECK(jsonb_typeof(data)='object'),
 PRIMARY KEY(source,id),
 CHECK((object_type IS NULL)=(object_id IS NULL))
);
ALTER TABLE history.events ENABLE ROW LEVEL SECURITY;
CREATE INDEX IF NOT EXISTS history_events_order ON history.events(recorded_at DESC,source DESC,id DESC);
CREATE INDEX IF NOT EXISTS history_events_user_order ON history.events(scope_id,recorded_at DESC,source DESC,id DESC) WHERE scope_type='user';
CREATE INDEX IF NOT EXISTS history_events_type_order ON history.events(type_id,recorded_at DESC,source DESC,id DESC);
CREATE INDEX IF NOT EXISTS history_events_object ON history.events(object_type,object_id,recorded_at DESC,source DESC,id DESC);
CREATE INDEX IF NOT EXISTS history_events_occurred ON history.events(occurred_at);
CREATE INDEX IF NOT EXISTS history_types_category ON history.sys_types(category_id,id);
COMMENT ON SCHEMA history IS 'Данные самостоятельного сервиса неизменяемой истории';
COMMENT ON TABLE history.migrations IS 'Журнал применённых миграций владельца истории';
COMMENT ON COLUMN history.migrations.version IS 'Номер атомарной миграции';
COMMENT ON COLUMN history.migrations.applied_at IS 'Время применения миграции PostgreSQL';
COMMENT ON TABLE history.sys_categories IS 'Системный справочник категорий событий; ID и code имеют неизменную семантику';
COMMENT ON COLUMN history.sys_categories.id IS 'Стабильный ID; новый ID назначает PostgreSQL';
COMMENT ON COLUMN history.sys_categories.code IS 'Стабильный уникальный английский код категории';
COMMENT ON COLUMN history.sys_categories.name IS 'Изменяемое русское название категории';
COMMENT ON COLUMN history.sys_categories.description IS 'Изменяемое краткое описание категории';
COMMENT ON TABLE history.sys_types IS 'Системный справочник типов событий; принадлежность категории неизменна';
COMMENT ON COLUMN history.sys_types.id IS 'Стабильный ID; новый ID назначает PostgreSQL';
COMMENT ON COLUMN history.sys_types.category_id IS 'Неизменяемая ссылка на категорию события';
COMMENT ON COLUMN history.sys_types.code IS 'Стабильный уникальный английский код типа';
COMMENT ON COLUMN history.sys_types.name IS 'Изменяемое русское название типа';
COMMENT ON COLUMN history.sys_types.description IS 'Изменяемое краткое описание типа';
COMMENT ON TABLE history.events IS 'Неизменяемые события; рабочие роли могут только добавлять и читать разрешённые строки';
COMMENT ON COLUMN history.events.id IS 'Созданный источником UUID события для безопасного повтора';
COMMENT ON COLUMN history.events.source IS 'Код сервиса-источника; уникальность определяется вместе с ID';
COMMENT ON COLUMN history.events.type_id IS 'Тип события; категория определяется через справочник';
COMMENT ON COLUMN history.events.occurred_at IS 'Время события у источника с точностью микросекунд';
COMMENT ON COLUMN history.events.recorded_at IS 'Время записи, назначенное PostgreSQL';
COMMENT ON COLUMN history.events.actor_id IS 'Заявленный инициатор без внешнего ключа в чужую БД';
COMMENT ON COLUMN history.events.scope_type IS 'Вид области видимости всего события';
COMMENT ON COLUMN history.events.scope_id IS 'Строковой ID области видимости всего события';
COMMENT ON COLUMN history.events.object_type IS 'Вид объекта у источника; передаётся вместе с object_id';
COMMENT ON COLUMN history.events.object_id IS 'Строковой ID объекта у источника';
COMMENT ON COLUMN history.events.data IS 'JSON-объект дополнительных сведений; не отдельные предметные колонки';
DO $seed$
DECLARE
 categories CONSTANT jsonb := '[{"id": 1, "code": "object", "name": "Объекты", "description": "Создание, изменение и удаление записей"}, {"id": 2, "code": "lifecycle", "name": "Жизненный цикл", "description": "Изменение доступности и срока жизни объекта"}, {"id": 3, "code": "state", "name": "Состояние", "description": "Переход объекта между состояниями"}, {"id": 4, "code": "relationship", "name": "Связи и структура", "description": "Изменение связей и расположения объектов"}, {"id": 5, "code": "ownership", "name": "Ответственность", "description": "Назначение ответственных и передача владения"}, {"id": 6, "code": "approval", "name": "Согласование", "description": "Рассмотрение и принятие решений"}, {"id": 7, "code": "publication", "name": "Публикация", "description": "Открытие доступа к опубликованным материалам и выпуск версий"}, {"id": 8, "code": "permission", "name": "Права", "description": "Изменение разрешений на действия"}, {"id": 9, "code": "access", "name": "Доступ к данным", "description": "Просмотр, скачивание и предоставление доступа"}, {"id": 10, "code": "identity", "name": "Идентификация и сессии", "description": "Вход, выход и изменения учётных данных"}, {"id": 11, "code": "exchange", "name": "Обмен данными", "description": "Передача и синхронизация данных"}, {"id": 12, "code": "execution", "name": "Выполнение операций", "description": "Запуск, управление и повтор операций"}, {"id": 13, "code": "configuration", "name": "Настройки и подключения", "description": "Изменение конфигурации и соединений"}, {"id": 14, "code": "observation", "name": "Наблюдения", "description": "Обнаружение условий, отклонений и исправлений сведений"}]'::jsonb;
 types CONSTANT jsonb := '[{"id": 101, "category_id": 1, "code": "create", "name": "Создание", "description": "Создан новый объект или запись"}, {"id": 102, "category_id": 1, "code": "update", "name": "Изменение", "description": "Изменены данные существующего объекта"}, {"id": 103, "category_id": 1, "code": "delete", "name": "Удаление", "description": "Объект удалён источником"}, {"id": 104, "category_id": 1, "code": "restore", "name": "Восстановление", "description": "Возвращён ранее удалённый объект"}, {"id": 105, "category_id": 1, "code": "copy", "name": "Копирование", "description": "Создана копия объекта"}, {"id": 201, "category_id": 2, "code": "archive", "name": "Архивация", "description": "Объект переведён в архив"}, {"id": 202, "category_id": 2, "code": "unarchive", "name": "Разархивация", "description": "Объект возвращён из архива"}, {"id": 203, "category_id": 2, "code": "activate", "name": "Активация", "description": "Объект включён для использования"}, {"id": 204, "category_id": 2, "code": "deactivate", "name": "Деактивация", "description": "Использование объекта приостановлено"}, {"id": 205, "category_id": 2, "code": "expire", "name": "Истечение срока", "description": "Завершился установленный срок действия"}, {"id": 301, "category_id": 3, "code": "transition", "name": "Смена состояния", "description": "Объект перешёл в другое состояние"}, {"id": 401, "category_id": 4, "code": "link", "name": "Связывание", "description": "Создана связь между объектами"}, {"id": 402, "category_id": 4, "code": "unlink", "name": "Разрыв связи", "description": "Удалена связь между объектами"}, {"id": 403, "category_id": 4, "code": "move", "name": "Перемещение", "description": "Изменено расположение или родитель объекта"}, {"id": 404, "category_id": 4, "code": "merge", "name": "Объединение", "description": "Несколько объектов объединены"}, {"id": 405, "category_id": 4, "code": "split", "name": "Разделение", "description": "Объект разделён на несколько объектов"}, {"id": 501, "category_id": 5, "code": "assign", "name": "Назначение", "description": "Назначен ответственный или исполнитель"}, {"id": 502, "category_id": 5, "code": "unassign", "name": "Снятие назначения", "description": "Снято назначение ответственного или исполнителя"}, {"id": 503, "category_id": 5, "code": "transfer", "name": "Передача владения", "description": "Изменён владелец объекта"}, {"id": 601, "category_id": 6, "code": "submit", "name": "Передача на рассмотрение", "description": "Объект передан на согласование"}, {"id": 602, "category_id": 6, "code": "approve", "name": "Одобрение", "description": "Принято положительное решение"}, {"id": 603, "category_id": 6, "code": "reject", "name": "Отклонение", "description": "Принято отрицательное решение"}, {"id": 604, "category_id": 6, "code": "rescind", "name": "Отзыв решения", "description": "Ранее принятое решение отозвано"}, {"id": 701, "category_id": 7, "code": "publish", "name": "Публикация", "description": "Материал опубликован для выбранной аудитории"}, {"id": 702, "category_id": 7, "code": "unpublish", "name": "Снятие с публикации", "description": "Публикация материала прекращена"}, {"id": 703, "category_id": 7, "code": "release", "name": "Выпуск версии", "description": "Выпущена версия продукта или материала"}, {"id": 801, "category_id": 8, "code": "grant", "name": "Предоставление прав", "description": "Предоставлено разрешение на действие"}, {"id": 802, "category_id": 8, "code": "revoke", "name": "Отзыв прав", "description": "Отозвано разрешение на действие"}, {"id": 803, "category_id": 8, "code": "adjust", "name": "Изменение прав", "description": "Изменён набор или уровень разрешений"}, {"id": 901, "category_id": 9, "code": "view", "name": "Просмотр", "description": "Зафиксирован просмотр данных"}, {"id": 902, "category_id": 9, "code": "download", "name": "Скачивание", "description": "Зафиксировано скачивание данных"}, {"id": 903, "category_id": 9, "code": "share", "name": "Предоставление доступа", "description": "Данные предоставлены выбранному получателю"}, {"id": 1001, "category_id": 10, "code": "login", "name": "Вход", "description": "Выполнен вход в систему"}, {"id": 1002, "category_id": 10, "code": "logout", "name": "Выход", "description": "Выполнен выход из системы"}, {"id": 1003, "category_id": 10, "code": "invalidate", "name": "Отзыв сессии", "description": "Сессия принудительно прекращена"}, {"id": 1004, "category_id": 10, "code": "rotate", "name": "Смена учётных данных", "description": "Заменены учётные данные или ключ"}, {"id": 1101, "category_id": 11, "code": "import", "name": "Импорт", "description": "Данные загружены из внешнего источника"}, {"id": 1102, "category_id": 11, "code": "export", "name": "Экспорт", "description": "Данные выгружены из системы"}, {"id": 1103, "category_id": 11, "code": "synchronize", "name": "Синхронизация", "description": "Данные согласованы между источниками"}, {"id": 1104, "category_id": 11, "code": "send", "name": "Отправка", "description": "Данные переданы отправителем"}, {"id": 1105, "category_id": 11, "code": "receive", "name": "Получение", "description": "Данные приняты получателем"}, {"id": 1106, "category_id": 11, "code": "deliver", "name": "Доставка", "description": "Подтверждена доставка получателю"}, {"id": 1201, "category_id": 12, "code": "execute", "name": "Выполнение", "description": "Зафиксировано выполнение операции"}, {"id": 1202, "category_id": 12, "code": "cancel", "name": "Отмена", "description": "Операция отменена"}, {"id": 1203, "category_id": 12, "code": "rollback", "name": "Откат", "description": "Восстановлено состояние до операции"}, {"id": 1204, "category_id": 12, "code": "compensate", "name": "Компенсация", "description": "Выполнено компенсирующее действие"}, {"id": 1205, "category_id": 12, "code": "schedule", "name": "Планирование", "description": "Операция назначена на будущее время"}, {"id": 1206, "category_id": 12, "code": "trigger", "name": "Срабатывание", "description": "Условие вызвало запуск действия"}, {"id": 1207, "category_id": 12, "code": "pause", "name": "Приостановка", "description": "Выполнение временно остановлено"}, {"id": 1208, "category_id": 12, "code": "resume", "name": "Возобновление", "description": "Выполнение продолжено после паузы"}, {"id": 1209, "category_id": 12, "code": "retry", "name": "Повторная попытка", "description": "Источник начал новую попытку бизнес-операции"}, {"id": 1301, "category_id": 13, "code": "configure", "name": "Изменение настроек", "description": "Изменены параметры работы"}, {"id": 1302, "category_id": 13, "code": "connect", "name": "Подключение", "description": "Установлено подключение к системе"}, {"id": 1303, "category_id": 13, "code": "disconnect", "name": "Отключение", "description": "Подключение прекращено"}, {"id": 1401, "category_id": 14, "code": "detect", "name": "Обнаружение условия", "description": "Обнаружено значимое условие или факт"}, {"id": 1402, "category_id": 14, "code": "exceed", "name": "Превышение порога", "description": "Значение вышло за установленный предел"}, {"id": 1403, "category_id": 14, "code": "anomaly", "name": "Обнаружение аномалии", "description": "Обнаружено необычное поведение или значение"}, {"id": 1404, "category_id": 14, "code": "correct", "name": "Исправление сведений", "description": "Новым событием уточнены ранее записанные сведения"}]'::jsonb;
 seed_row jsonb;
 inserted_row jsonb;
 new_categories jsonb := '[]'::jsonb;
 new_types jsonb := '[]'::jsonb;
 table_name text;
 event_id uuid;
 request jsonb;
 audit_data jsonb;
BEGIN
 FOR seed_row IN SELECT value FROM jsonb_array_elements(categories) LOOP
  IF EXISTS(SELECT 1 FROM history.sys_categories WHERE (id=(seed_row->>'id')::integer OR code=seed_row->>'code') AND (id<>(seed_row->>'id')::integer OR code<>seed_row->>'code')) THEN
   RAISE EXCEPTION 'HISTORY_SEED_CATEGORY_CONFLICT';
  END IF;
  inserted_row := NULL;
  INSERT INTO history.sys_categories(id,code,name,description) VALUES((seed_row->>'id')::integer,seed_row->>'code',seed_row->>'name',seed_row->>'description') ON CONFLICT(id) DO NOTHING RETURNING to_jsonb(sys_categories.*) INTO inserted_row;
  IF inserted_row IS NOT NULL THEN new_categories := new_categories || jsonb_build_array(inserted_row); END IF;
 END LOOP;
 FOR seed_row IN SELECT value FROM jsonb_array_elements(types) LOOP
  IF EXISTS(SELECT 1 FROM history.sys_types WHERE (id=(seed_row->>'id')::integer OR code=seed_row->>'code') AND (id<>(seed_row->>'id')::integer OR code<>seed_row->>'code' OR category_id<>(seed_row->>'category_id')::integer)) THEN
   RAISE EXCEPTION 'HISTORY_SEED_TYPE_CONFLICT';
  END IF;
  inserted_row := NULL;
  INSERT INTO history.sys_types(id,category_id,code,name,description) VALUES((seed_row->>'id')::integer,(seed_row->>'category_id')::integer,seed_row->>'code',seed_row->>'name',seed_row->>'description') ON CONFLICT(id) DO NOTHING RETURNING to_jsonb(sys_types.*) INTO inserted_row;
  IF inserted_row IS NOT NULL THEN new_types := new_types || jsonb_build_array(inserted_row); END IF;
 END LOOP;
 FOR table_name IN SELECT unnest(ARRAY['sys_categories','sys_types']) LOOP
  FOR inserted_row IN SELECT value FROM jsonb_array_elements(CASE WHEN table_name='sys_categories' THEN new_categories ELSE new_types END) LOOP
   event_id := md5('history:seed:v1:' || table_name || ':' || (inserted_row->>'id'))::uuid;
   request := (inserted_row - 'id') || jsonb_build_object('event_id',event_id,'actor_id',NULL);
   audit_data := jsonb_build_object('operation',CASE WHEN table_name='sys_categories' THEN 'history_category_create' ELSE 'history_type_create' END,'request',request,'old',NULL,'new',inserted_row,'result',inserted_row);
   IF EXISTS(SELECT 1 FROM history.events WHERE source='service_history' AND id=event_id) THEN RAISE EXCEPTION 'HISTORY_SEED_AUDIT_CONFLICT'; END IF;
   INSERT INTO history.events(id,source,type_id,occurred_at,actor_id,scope_type,scope_id,object_type,object_id,data)
    VALUES(event_id,'service_history',101,clock_timestamp(),NULL,'system','service_history',table_name,inserted_row->>'id',audit_data);
  END LOOP;
 END LOOP;
 PERFORM setval(pg_get_serial_sequence('history.sys_categories','id'),GREATEST((SELECT max(id) FROM history.sys_categories),(SELECT last_value FROM history.sys_categories_id_seq)),true);
 PERFORM setval(pg_get_serial_sequence('history.sys_types','id'),GREATEST((SELECT max(id) FROM history.sys_types),(SELECT last_value FROM history.sys_types_id_seq)),true);
END $seed$;
INSERT INTO history.migrations(version) VALUES(1) ON CONFLICT(version) DO NOTHING;
